.voecsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2620;
    background:
        repeating-linear-gradient(135deg, rgba(120, 92, 58, 0.035) 0px, rgba(120, 92, 58, 0.035) 1px, transparent 1px, transparent 11px),
        linear-gradient(170deg, #f6efe3 0%, #efe5d4 60%, #e7dac3 100%);
    border-radius: 16px;
    border: 1px solid #d8c7a8;
}

.voecsim-container * {
    box-sizing: border-box;
}

.voecsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #2f3a36 0%, #3c4a3f 50%, #5a4a30 100%);
    color: #f6efe3;
    border-radius: 14px;
    margin-bottom: 20px;
    border: 1px solid #46402f;
    box-shadow: 0 12px 30px rgba(40, 34, 22, 0.35);
}

.voecsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fbf6ec;
    text-transform: uppercase;
}

.voecsim-header-tag {
    display: inline-block;
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f0a93f;
    background: rgba(240, 169, 63, 0.13);
    border: 1px solid rgba(240, 169, 63, 0.35);
    padding: 5px 14px;
    border-radius: 6px;
}

.voecsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ddd2bd;
}

.voecsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6c5f47;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.voecsim-period-counter #currentDay,
.voecsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #b35e1f;
}

.voecsim-round-name {
    background: rgba(179, 94, 31, 0.14);
    color: #9a4f17;
    padding: 3px 12px;
    border-radius: 6px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.voecsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3b1f;
    background: rgba(196, 78, 42, 0.12);
    border: 1px solid rgba(196, 78, 42, 0.32);
    padding: 4px 12px;
    border-radius: 6px;
}

.voecsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.voecsim-status-card {
    background: linear-gradient(160deg, #fffdf8 0%, #f3ead8 100%);
    border-radius: 12px;
    padding: 16px 16px 14px;
    border: 1px solid #ddccac;
    box-shadow: 0 5px 16px rgba(90, 70, 40, 0.12);
    border-top: 4px solid #8a7a5a;
}

.voecsim-card-fill { border-top-color: #2e8b57; }
.voecsim-card-wc { border-top-color: #c47a2a; }
.voecsim-card-agility { border-top-color: #2f6fa3; }
.voecsim-card-tlc { border-top-color: #b3502a; }

.voecsim-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #8a7a5a;
}

.voecsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2b2620;
    font-variant-numeric: tabular-nums;
}

.voecsim-card-fill .voecsim-value { color: #2e8b57; }
.voecsim-card-wc .voecsim-value { color: #c47a2a; }
.voecsim-card-agility .voecsim-value { color: #2f6fa3; }
.voecsim-card-tlc .voecsim-value { color: #b3502a; }

.voecsim-sublabel {
    font-size: 0.75rem;
    color: #8a7a5a;
    line-height: 1.35;
}

/* state-driven highlight classes */
.voecsim-fill-good .voecsim-value { color: #1f7a45; }
.voecsim-fill-bad .voecsim-value { color: #c0392b; }
.voecsim-wc-breach { border-top-color: #c0392b; }
.voecsim-wc-breach .voecsim-value { color: #c0392b; }
.voecsim-wc-safe { border-top-color: #2e8b57; }
.voecsim-wc-safe .voecsim-value { color: #1f7a45; }
.voecsim-tlc-good .voecsim-value { color: #1f7a45; }
.voecsim-tlc-bad .voecsim-value { color: #c0392b; }

.voecsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffdf8;
    border: 1px solid #ddccac;
    color: #5a4a30;
    padding: 10px 18px;
    border-radius: 10px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.voecsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #b35e1f;
}

.voecsim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #fffdf8 0%, #f4ecda 100%);
    border-left: 5px solid #c47a2a;
    border-radius: 10px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 5px 16px rgba(90, 70, 40, 0.10);
}

.voecsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.voecsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #5a4a30;
    margin-bottom: 6px;
}

.voecsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a4234;
}

.voecsim-briefing-text strong { color: #b35e1f; }
.voecsim-briefing-text em { color: #2e8b57; font-style: italic; }

.voecsim-controls {
    background: linear-gradient(160deg, #fffdf8 0%, #f1e8d5 100%);
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ddccac;
    box-shadow: 0 5px 16px rgba(90, 70, 40, 0.10);
}

.voecsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #5a4a30;
    border-bottom: 2px solid #e1d3b6;
    padding-bottom: 8px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.voecsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #4a4234;
    margin: 14px 0 6px;
}

.voecsim-container select,
.voecsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c9b78f;
    border-radius: 8px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #2b2620;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.voecsim-container select:focus,
.voecsim-container input[type="number"]:focus {
    outline: none;
    border-color: #c47a2a;
    box-shadow: 0 0 0 3px rgba(196, 122, 42, 0.20);
}

.voecsim-container select option {
    background-color: #fffdf8;
    color: #2b2620;
}

.voecsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c47a2a;
}

.voecsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6c5f47;
    margin-top: 4px;
}

.voecsim-range-readout span:nth-child(2) {
    color: #b35e1f;
    font-weight: 800;
}

.voecsim-hint {
    font-size: 0.8rem;
    color: #8a7a5a;
    margin-top: 4px;
    line-height: 1.4;
    background: rgba(196, 122, 42, 0.07);
    border-left: 3px solid rgba(196, 122, 42, 0.45);
    padding: 6px 10px;
    border-radius: 0 6px 6px 0;
}

.voecsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.voecsim-container .btn-primary {
    background: linear-gradient(135deg, #9a4f17 0%, #d4862e 100%);
    border: none;
    color: #fff7ea;
    padding: 11px 28px;
    border-radius: 8px;
    box-shadow: 0 8px 18px rgba(154, 79, 23, 0.35);
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

.voecsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.voecsim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c9b78f;
    color: #6c5f47;
    background: transparent;
}

.voecsim-coach {
    background: linear-gradient(160deg, #2f3a36 0%, #3a3326 100%);
    color: #e8ddc8;
    border: 1px solid #46402f;
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(40, 34, 22, 0.30);
}

.voecsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0a93f;
    margin-bottom: 8px;
}

.voecsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.voecsim-coach-body strong { color: #f0a93f; }
.voecsim-coach-body em { color: #7fc99b; font-style: italic; }

.voecsim-history,
.voecsim-chart {
    background: linear-gradient(160deg, #fffdf8 0%, #f1e8d5 100%);
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ddccac;
    box-shadow: 0 5px 16px rgba(90, 70, 40, 0.10);
}

.voecsim-history h3,
.voecsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #5a4a30;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.voecsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a4234;
}

.voecsim-container table#usfHistoryTable th {
    background: #efe2c8;
    color: #9a4f17;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d8c7a8;
}

.voecsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e6d9bf;
    color: #4a4234;
}

.voecsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8f1e2;
}

.voecsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .voecsim-container {
        padding: 14px;
    }
    .voecsim-header h1 {
        font-size: 1.7rem;
    }
    .voecsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .voecsim-value {
        font-size: 2rem;
    }
    .voecsim-clock {
        margin-left: 0;
    }
    .voecsim-period-counter {
        font-size: 0.88rem;
    }
    .voecsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .voecsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* === voecsim-cm: completion debrief (appended, adapter 1.1.0) === */
.voecsim-cm { max-width: 640px; margin: 0 auto; font-family: inherit; }
.voecsim-cm-head { display: flex; align-items: baseline; gap: 14px; flex-wrap: wrap; margin-bottom: 14px; }
.voecsim-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #0b3d5c; }
.voecsim-cm-max { font-size: 1.1rem; font-weight: 600; color: #6b7a86; margin-left: 2px; }
.voecsim-cm-grade { font-size: 1.25rem; font-weight: 700; color: #123; }
.voecsim-cm-badges { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.voecsim-cm-badge { font-size: .82rem; font-weight: 600; padding: 4px 10px; border-radius: 999px; border: 1px solid transparent; }
.voecsim-cm-ok { background: #e4f5ea; color: #1c7a43; border-color: #b7e2c7; }
.voecsim-cm-no { background: #fdecec; color: #b23b3b; border-color: #f3c4c4; }
.voecsim-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(96px, 1fr)); gap: 10px; margin-bottom: 16px; }
.voecsim-cm-kpi { background: #f4f7f9; border: 1px solid #e1e8ed; border-radius: 8px; padding: 10px 8px; text-align: center; }
.voecsim-cm-kpi-v { font-size: 1.2rem; font-weight: 700; color: #0b3d5c; }
.voecsim-cm-kpi-l { font-size: .74rem; color: #6b7a86; margin-top: 3px; }
.voecsim-cm-insights { margin: 0; padding-left: 20px; }
.voecsim-cm-insights li { margin: 5px 0; line-height: 1.4; }

