(function() {
    'use strict';

    class VoecAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Agile or Lean?`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (VOEC) — USD.
            this.LINE = 110;            // US$110M revolving facility
            this.DRAWN = 98;            // drawn to US$98M
            this.INV_START = 96;        // US$96M inventory on hand
            this.BREACH_INV = 110;      // inventory above the line triggers the covenant
            this.AIR = 4.20;           // US$/unit air freight
            this.OCEAN = 0.45;         // US$/unit ocean freight
            this.SLOW_BASICS = 22;      // US$22M slow basics at markdown risk
            this.UNSERVED = 14;         // ~US$14M full-margin demand unserved

            // Concept truths (best answers).
            this.TRUE_SEGMENT = `segment`;
            this.TRUE_RESILIENCE = `alertness`;
            this.TRUE_SOURCING = `leagile`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    fill: 82,                 // overall fill rate % (target 95)
                    wcHeadroom: 12,           // US$M headroom on the line (110 - 98 drawn)
                    agility: 28,              // alertness × responsiveness index 0-100
                    tlc: 0,                   // total logistics cost impact US$M vs status quo (lower better)
                    inventory: 96,            // US$M inventory on hand
                    alertnessBuilt: false,    // standing alertness capability acquired
                    decoupled: false,         // leagile decoupling point placed
                    breached: false,          // covenant breached this run
                    blanketBuffer: false,     // blanket safety-stock error committed
                    singleShock: false,       // designed only for this shock
                    fillHistory: [82],
                    agilityHistory: [28],
                    headroomHistory: [12],
                    tlcHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately middling / wrong-leaning mix —
                // a blind click-through must NOT auto-win.
                state.decisions = {
                    segment: `lean_all`,
                    resilience: `preparedness`,
                    focus: 50,
                    sourcing: `lean`,
                    buffer: 12,
                    bufferTarget: `blanket`,
                    expedite: 50,
                    marginTest: `all`,
                    markdown: `hold`,
                    alertness: 0,
                    config: `overbuilt`,
                    capability: `patch`,
                    nextShock: `thisonly`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const sg = document.getElementById(`segmentInput`);
                const rs = document.getElementById(`resilienceInput`);
                const fc = document.getElementById(`focusInput`);
                if (sg) decisions.segment = sg.value;
                if (rs) decisions.resilience = rs.value;
                if (fc) decisions.focus = parseInt(fc.value, 10);
                if (!Number.isFinite(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                    warn(`warn_focus_range`); return false;
                }
            } else if (round === 2) {
                const sr = document.getElementById(`sourcingInput`);
                const bf = document.getElementById(`bufferInput`);
                const bt = document.getElementById(`bufferTargetInput`);
                if (sr) decisions.sourcing = sr.value;
                if (bf) decisions.buffer = parseFloat(bf.value);
                if (bt) decisions.bufferTarget = bt.value;
                if (!Number.isFinite(decisions.buffer) || decisions.buffer < 0 || decisions.buffer > 30) {
                    warn(`warn_buffer_range`); return false;
                }
            } else if (round === 3) {
                const ex = document.getElementById(`expediteInput`);
                const mt = document.getElementById(`marginTestInput`);
                const md = document.getElementById(`markdownInput`);
                const al = document.getElementById(`alertnessInput`);
                if (ex) decisions.expedite = parseInt(ex.value, 10);
                if (mt) decisions.marginTest = mt.value;
                if (md) decisions.markdown = md.value;
                if (al) decisions.alertness = parseFloat(al.value);
                if (!Number.isFinite(decisions.expedite) || decisions.expedite < 0 || decisions.expedite > 100) {
                    warn(`warn_expedite_range`); return false;
                }
                if (!Number.isFinite(decisions.alertness) || decisions.alertness < 0) {
                    warn(`warn_alertness_value`); return false;
                }
            } else if (round === 4) {
                const cf = document.getElementById(`configInput`);
                const cp = document.getElementById(`capabilityInput`);
                const ns = document.getElementById(`nextShockInput`);
                const cv = document.getElementById(`convictionInput`);
                if (cf) decisions.config = cf.value;
                if (cp) decisions.capability = cp.value;
                if (ns) decisions.nextShock = ns.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let fillDelta = 0, agilityDelta = 0, invDelta = 0, tlcDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // DIAGNOSE — segment by demand type, name the worst resilience dimension.
                // Common Error 2 (one-size-fits-all) is set up here.
                switch (d.segment) {
                    case `segment`: agilityDelta += 12; tlcDelta -= 1; coachKey = `coach_r1_segment`; break;
                    case `lean_all`: agilityDelta -= 4; tlcDelta += 2; coachKey = `coach_r1_leanall`; break;
                    case `agile_all`: agilityDelta += 2; tlcDelta += 4; coachKey = `coach_r1_agileall`; break;
                    case `volume`: agilityDelta += 2; tlcDelta += 1; coachKey = `coach_r1_volume`; break;
                }

                // Goldsby resilience self-assessment. The bite is alertness (Decision Tree #4).
                switch (d.resilience) {
                    case `alertness`: agilityDelta += 8; coachKey = (d.segment === `segment`) ? `coach_r1_sharp` : coachKey; break;
                    case `preparedness`: agilityDelta -= 2; coachKey = `coach_r1_preparedness`; break;
                    case `agility`: agilityDelta += 2; break;
                    case `fine`: agilityDelta -= 6; tlcDelta += 2; coachKey = `coach_r1_fine`; break;
                }

                if (d.focus >= 60) { agilityDelta += 5; }
                else if (d.focus <= 25) { agilityDelta -= 4; coachKey = `coach_r1_lowfocus`; }

                summaryKey = (d.segment === `segment` && d.resilience === `alertness`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // PLAN — sourcing architecture + buffer size + buffer placement.
                // Common Errors 1 (blanket buffer) and 2 (one-size sourcing).
                switch (d.sourcing) {
                    case `leagile`:
                        ds.decoupled = true; agilityDelta += 14; fillDelta += 6; tlcDelta -= 2; coachKey = `coach_r2_leagile`; break;
                    case `lean`:
                        agilityDelta -= 6; fillDelta -= 4; tlcDelta += 3; coachKey = `coach_r2_lean`; break;     // hot SKU still starved
                    case `agile`:
                        agilityDelta += 6; fillDelta += 4; tlcDelta += 6; coachKey = `coach_r2_agile`; break;     // basics 14% dearer (Decision Tree #2)
                }

                // Buffer build consumes the line. Over US$14M breaches (96 + 14 = 110).
                invDelta += d.buffer;

                // Buffer placement — selective beats blanket (Decision Tree #1).
                let bufferFillGain = 0;
                switch (d.bufferTarget) {
                    case `variable`:
                        bufferFillGain = d.buffer * 0.55; agilityDelta += 6; tlcDelta -= 1; coachKey = (d.sourcing === `leagile`) ? `coach_r2_selective` : coachKey; break;
                    case `blanket`:
                        bufferFillGain = d.buffer * 0.30; ds.blanketBuffer = (d.buffer >= 12); tlcDelta += 2; if (d.buffer >= 12) coachKey = `coach_r2_blanket`; break;
                    case `basics`:
                        bufferFillGain = d.buffer * 0.15; tlcDelta += 3; coachKey = `coach_r2_basics`; break;     // trapped cash on predictable line
                }
                fillDelta += bufferFillGain;

                summaryKey = (d.sourcing === `leagile` && d.bufferTarget === `variable` && d.buffer <= 14) ? `sum_r2_good` :
                             (d.buffer > 14 ? `sum_r2_breach` : `sum_r2_weak`);
            } else if (round === 3) {
                // DECIDE — expedite (with margin test), markdown, alertness.
                // Common Errors 3 (indiscriminate air) and 4 (agility without alertness).
                const air = d.expedite / 100;

                // Expedite recovers fill on the viral SKU but freight premium hits TLC.
                // The margin test decides whether the premium is justified.
                fillDelta += air * 14;                                    // recovered service on the hot line
                const freightPremium = air * (this.AIR - this.OCEAN) * 2.2; // ~US$M premium scaled to the lane

                switch (d.marginTest) {
                    case `test`:
                        // Fly only the margin-positive hot units — premium is justified.
                        tlcDelta += freightPremium * 0.45;
                        agilityDelta += 6;
                        coachKey = `coach_r3_test`;
                        break;
                    case `all`:
                        // Firehose the whole container — basics flown at near-zero margin (Decision Tree #3).
                        tlcDelta += freightPremium * 1.6;
                        if (air >= 0.6) coachKey = `coach_r3_firehose`;
                        else coachKey = `coach_r3_alltest`;
                        break;
                    case `none`:
                        // Wait for ocean — eat the stockout on the full-margin SKU.
                        fillDelta -= air * 14;                            // cancel the recovery we credited
                        fillDelta -= 5;
                        tlcDelta += 6;                                    // lost full-margin demand
                        coachKey = `coach_r3_nofly`;
                        break;
                }

                // Markdown vs hold — the slow basics (Decision Tree #5: linked to the stockout).
                switch (d.markdown) {
                    case `clear`:
                        invDelta -= 10; tlcDelta -= 2; fillDelta += 2; coachKey = (coachKey === `coach_r3_test`) ? `coach_r3_linked` : coachKey; break;
                    case `hold`:
                        tlcDelta += 4; coachKey = `coach_r3_hold`; break;     // trapped cash, future markdown
                    case `dump`:
                        invDelta -= 14; tlcDelta += 5; break;                 // cash freed but margin destroyed
                }

                // ALERTNESS investment — standing capability, distinct from agility (Decision Tree #4).
                invDelta += d.alertness;
                switch (d.alertness) {
                    case 4:
                        ds.alertnessBuilt = true; agilityDelta += 14; fillDelta += 3; break;
                    case 2:
                        agilityDelta += 6; break;
                    default: // 0
                        // Agility without alertness — speed you cannot aim.
                        if (ds.decoupled || d.sourcing === `agile`) { agilityDelta -= 8; coachKey = `coach_r3_noalert`; }
                        break;
                }

                summaryKey = (d.marginTest === `test` && d.alertness >= 2 && d.markdown === `clear`) ? `sum_r3_good` :
                             (d.marginTest === `all` && air >= 0.6 ? `sum_r3_firehose` :
                             (d.alertness === 0 ? `sum_r3_blind` : `sum_r3_weak`));
            } else if (round === 4) {
                // RECOVER — commit the configuration; capability vs patch; next-shock robustness.
                // Common Error 5 (single-shock design).
                switch (d.config) {
                    case `coherent`: agilityDelta += 12; fillDelta += 4; tlcDelta -= 3; coachKey = `coach_r4_coherent`; break;
                    case `overbuilt`: invDelta += 12; tlcDelta += 6; agilityDelta += 2; coachKey = `coach_r4_overbuilt`; break;
                    case `status`: agilityDelta -= 10; fillDelta -= 4; tlcDelta += 4; ds.singleShock = true; coachKey = `coach_r4_status`; break;
                }

                switch (d.capability) {
                    case `capability`: agilityDelta += 8; tlcDelta -= 1; break;
                    case `patch`: agilityDelta -= 4; ds.singleShock = true; coachKey = (coachKey === `coach_r4_coherent`) ? `coach_r4_patch` : coachKey; break;
                }

                switch (d.nextShock) {
                    case `robust`: agilityDelta += 8; if (d.config === `coherent` && ds.alertnessBuilt) coachKey = `coach_r4_robust`; break;
                    case `thisonly`: agilityDelta -= 6; ds.singleShock = true; coachKey = `coach_r4_thisonly`; break;
                }

                if (d.conviction >= 60) { agilityDelta += 4; }
                else if (d.conviction <= 25) { agilityDelta -= 4; }

                summaryKey = (d.config === `coherent` && d.capability === `capability` && d.nextShock === `robust`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Inventory & working-capital accounting.
            ds.inventory = Math.max(60, Math.round((ds.inventory + invDelta) * 10) / 10);
            ds.wcHeadroom = Math.round((this.LINE - ds.inventory) * 10) / 10;
            if (ds.inventory > this.BREACH_INV) {
                // Covenant breach — the bank intervenes; agility and TLC both punished.
                ds.breached = true;
                agilityDelta -= 10;
                tlcDelta += 5;
                if (coachKey === `coach_default` || round === 2) coachKey = `coach_breach`;
            }

            // Apply KPI deltas, clamped.
            ds.fill = Math.max(0, Math.min(100, Math.round((ds.fill + fillDelta) * 10) / 10));
            ds.agility = Math.max(0, Math.min(100, Math.round(ds.agility + agilityDelta)));
            ds.tlc = Math.round((ds.tlc + tlcDelta) * 10) / 10;

            ds.fillHistory.push(ds.fill);
            ds.agilityHistory.push(ds.agility);
            ds.headroomHistory.push(ds.wcHeadroom);
            ds.tlcHistory.push(ds.tlc);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            return {
                period: state.currentPeriod,
                fill: ds.fill,
                fillDelta: Math.round(fillDelta * 10) / 10,
                agility: ds.agility,
                agilityDelta: Math.round(agilityDelta),
                wcHeadroom: ds.wcHeadroom,
                inventory: ds.inventory,
                tlc: ds.tlc,
                tlcDelta: Math.round(tlcDelta * 10) / 10,
                breached: ds.breached,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // USD only — US$ symbol everywhere. English style with 1 decimal.
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            return `${sign}US$${abs.toFixed(1)}M`;
        }

        _fmtPct(v) {
            return `${Math.round(Number(v))}%`;
