        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.fillHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                voecChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.fillHistory },
                        { data: ds.agilityHistory },
                        { data: ds.headroomHistory }
                    ]
                }
            };
        }

        // _composite(ds): single source of truth for the 0-100 score (v1.0.0 formula, verbatim).
        _composite(ds) {
            const fill = Math.round(ds.fill);
            const agility = Math.round(ds.agility);
            const headroom = ds.wcHeadroom;
            const tlc = ds.tlc;
            const headroomScore = Math.max(0, Math.min(100, (headroom + 20) / 40 * 100));
            const tlcScore = Math.max(-25, Math.min(25, -tlc * 2));
            return Math.round(fill * 0.30 + agility * 0.30 + headroomScore * 0.24 + (tlcScore + 25) * 0.16);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const fill = Math.round(ds.fill);
            const agility = Math.round(ds.agility);
            const headroom = ds.wcHeadroom;
            const tlc = ds.tlc;

            // Composite via _composite(ds) — single source of truth (v1.0.0 formula).
            const composite = this._composite(ds);

            const served = fill >= 92;
            const solvent = headroom > 0 && !ds.breached;
            const responsive = agility >= 60 && ds.alertnessBuilt;
            const durable = ds.decoupled && ds.alertnessBuilt && !ds.singleShock;

            let performanceKey = `grade_mismatch`;
            if (served && solvent && responsive && durable && composite >= 75) performanceKey = `grade_resilient`;
            else if (served && solvent && responsive) performanceKey = `grade_held`;
            else if (ds.breached) performanceKey = `grade_breached`;
            else if (ds.singleShock && composite < 60) performanceKey = `grade_singleshock`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (served && solvent && responsive && durable) insights.push(window.mySimulation.t(`insight_resilient`));
            else if (ds.breached) insights.push(window.mySimulation.t(`insight_breach`));
            else if (ds.singleShock) insights.push(window.mySimulation.t(`insight_singleshock`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (fill < 90) insights.push(window.mySimulation.t(`insight_fill_low`));
            else if (fill >= 95) insights.push(window.mySimulation.t(`insight_fill_target`));
            if (tlc > 6) insights.push(window.mySimulation.t(`insight_tlc_high`));
            else if (tlc < -2) insights.push(window.mySimulation.t(`insight_tlc_saved`));
            if (!ds.alertnessBuilt && agility >= 50) insights.push(window.mySimulation.t(`insight_blind`));
            if (ds.decoupled && ds.alertnessBuilt && headroom > 0) insights.push(window.mySimulation.t(`insight_leagile`));

            return {
                fill: fill,
                agility: agility,
                headroom: headroom,
                tlc: tlc,
                served: served,
                solvent: solvent,
                responsive: responsive,
                durable: durable,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: (served && solvent && responsive && durable),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const t = (k) => window.mySimulation.t(k);
            const esc = (x) => String(x == null ? `` : x).replace(/[&<>]/g, (c) => ({ '&': `&amp;`, '<': `&lt;`, '>': `&gt;` }[c]));
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || t(s.performanceKey || `grade_mismatch`);
            const badge = (ok, okKey, noKey) => `<span class="voecsim-cm-badge ${ok ? `voecsim-cm-ok` : `voecsim-cm-no`}">${esc(t(ok ? okKey : noKey))}</span>`;
            const kpi = (label, val) => `<div class="voecsim-cm-kpi"><div class="voecsim-cm-kpi-v">${esc(val)}</div><div class="voecsim-cm-kpi-l">${esc(label)}</div></div>`;
            const insights = (s.insights || []).map((i) => `<li>${esc(i)}</li>`).join(``);
            let badges = badge(s.served === true, `cm_badge_served`, `cm_badge_stockouts`)
                       + badge(s.solvent === true, `cm_badge_solvent`, `cm_badge_breach`)
                       + badge(s.responsive === true, `cm_badge_responsive`, `cm_badge_rigid`)
                       + badge(s.durable === true, `cm_badge_durable`, `cm_badge_fragile`);
            const headroom = (s.headroom != null) ? this._fmtMoney(Number(s.headroom)) : `\u2014`;
            const tlc = (s.tlc != null) ? this._fmtMoney(Number(s.tlc)) : `\u2014`;
            return `<div class="voecsim-cm">`
                + `<div class="voecsim-cm-head"><div class="voecsim-cm-score">${score}<span class="voecsim-cm-max">/100</span></div>`
                + `<div class="voecsim-cm-grade">${esc(grade)}</div></div>`
                + `<div class="voecsim-cm-badges">${badges}</div>`
                + `<div class="voecsim-cm-kpis">`
                + kpi(t(`cm_kpi_fill`), (s.fill != null ? s.fill + `%` : `\u2014`))
                + kpi(t(`cm_kpi_agility`), (s.agility != null ? s.agility : `\u2014`))
                + kpi(t(`cm_kpi_headroom`), headroom)
                + kpi(t(`cm_kpi_tlc`), tlc)
                + kpi(t(`cm_kpi_index`), score)
                + `</div>`
                + (insights ? `<ul class="voecsim-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.breached) return window.mySimulation.t(`hint_breach`);
            if (ds.inventory > 105) return window.mySimulation.t(`hint_inventory`);
            if (state.currentPeriod >= 3 && !ds.alertnessBuilt && ds.agility >= 45) return window.mySimulation.t(`hint_alertness`);
            if (ds.tlc >= 7) return window.mySimulation.t(`hint_tlc`);
            if (state.currentPeriod >= 2 && ds.fill < 86) return window.mySimulation.t(`hint_fill`);
            if (ds.decoupled && ds.alertnessBuilt && ds.fill >= 92 && ds.wcHeadroom > 0) return window.mySimulation.t(`hint_strong`);
            return null;
        }

